{
  "strategy_id": "agent_practical",
  "strategy_title": "클라우드 접근 권한 이해 및 과도한 권한 점검 (1주 집중)",
  "summary": "사용자의 1주(3시간/주) 가용 시간과 0원 예산을 반영하여, 클라우드 접근 권한(읽기/쓰기) 개념과 과도한 권한(Excessive Permissions) 3가지를 문서로 점검하는 실습 중심 로드맵을 설계했습니다. 실제 계정이나 외부 API 호출 없이 가상 시나리오를 기반으로 학습하며, 검색된 무료 자료(Microsoft Learn)와 규정(인재개발규정)을 활용합니다.",
  "project_goal": "가상 클라우드 서비스 환경에서 읽기/쓰기 권한 구조를 이해하고, 과도한 권한 3가지를 식별하여 점검 보고서로 작성한다.",
  "total_duration_weeks": 1,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "클라우드 권한 모델 기초 이해",
      "duration": "1.5시간",
      "focus": "IAM(Identity and Access Management) 개념, 읽기/쓰기 권한의 차이, 최소 권한 원칙 이해"
    },
    {
      "step": 2,
      "title": "가상 권한표 작성 및 과도한 권한 식별",
      "duration": "1.5시간",
      "focus": "가상 서비스(예: S3, Blob Storage)를 대상으로 읽기/쓰기 권한표를 작성하고, 과도한 권한 3가지(예: 전체 관리자 권한, 불필요한 쓰기 권한, 과도한 리소스 범위)를 식별"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "권한 모델 기초 학습",
      "duration": "1.5시간",
      "focus_goal": "클라우드 접근 권한의 기본 구조와 읽기/쓰기 권한의 차이를 이해한다.",
      "key_actions": [
        "Microsoft Learn의 Azure Well-Architected 프레임워크 소개 모듈 중 보안/거버넌스 관련 섹션 학습",
        "IAM 정책 구조(Principal, Action, Resource, Effect) 개념 정리",
        "읽기(Read)와 쓰기(Write) 권한의 실제 적용 사례 가상 시나리오로 분석"
      ],
      "deliverables": [
        "클라우드 권한 모델 개념 정리 노트 (1페이지)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_5f3eec6bc5b7"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "권한표 작성 및 과도한 권한 점검",
      "duration": "1.5시간",
      "focus_goal": "가상 서비스의 읽기/쓰기 권한표를 작성하고 과도한 권한 3가지를 문서로 점검한다.",
      "key_actions": [
        "가상 서비스(예: 문서 저장소, 데이터베이스)를 설정하고 역할별(관리자, 개발자, 일반 사용자) 읽기/쓰기 권한표 작성",
        "과도한 권한 3가지 식별: 1) 불필요한 전체 관리자 권한, 2) 읽기 전용 역할에 쓰기 권한 부여, 3) 특정 리소스 범위를 넘어선 권한",
        "각 과도한 권한의 위험성과 개선 방안(최소 권한 원칙 적용)을 문서화"
      ],
      "deliverables": [
        "가상 서비스 읽기/쓰기 권한표 (Excel 또는 Markdown)",
        "과도한 권한 3가지 점검 보고서 (위험성 및 개선 방안 포함)"
      ],
